// "What's around" on the listing page (P15-T02).
// 1. Turns the lists into tabs (arrow keys, Home, End; Tab moves on to the list).
//    Without this file all lists stay visible one under the other.
// 2. If the detail map (public/js/map.js) loads, offers a checkbox that draws ONE
//    dashed circle around the approximate centre: how far the nearest place of the
//    chosen kind is. A circle is a radius, not a position; no place is plotted.
// The server's text is only ever inserted as text, never as HTML.
(function () {
  "use strict";

  var root = document.querySelector("[data-neighborhood]");
  if (!root) return;

  var tablist = root.querySelector("[data-tablist]");
  var tabs = Array.prototype.slice.call(root.querySelectorAll("[role=tab]"));
  var panels = {};
  Array.prototype.forEach.call(root.querySelectorAll("[data-panel]"), function (panel) {
    panels[panel.getAttribute("data-panel")] = panel;
  });
  if (!tablist || tabs.length === 0) return;

  var rings = {};
  try {
    JSON.parse(root.getAttribute("data-rings") || "[]").forEach(function (ring) {
      if (ring && typeof ring.id === "string" && Number.isFinite(ring.radiusM) && ring.radiusM > 0) {
        rings[ring.id] = ring;
      }
    });
  } catch (err) {
    rings = {};
  }

  var current = null;

  function select(tab, focus) {
    current = tab.getAttribute("data-category");
    tabs.forEach(function (t) {
      var on = t === tab;
      t.setAttribute("aria-selected", on ? "true" : "false");
      t.setAttribute("tabindex", on ? "0" : "-1");
    });
    Object.keys(panels).forEach(function (id) {
      panels[id].hidden = id !== current;
    });
    if (focus) tab.focus();
    updateRing();
  }

  // Enhance: tabs visible, panels become tab panels, the first one shows.
  root.classList.add("is-tabbed");
  tablist.hidden = false;
  tabs.forEach(function (tab) {
    var id = tab.getAttribute("data-category");
    var panel = panels[id];
    if (panel) {
      panel.setAttribute("role", "tabpanel");
      panel.setAttribute("aria-labelledby", tab.id);
      panel.setAttribute("tabindex", "0");
    }
    tab.addEventListener("click", function () {
      select(tab, false);
    });
    tab.addEventListener("keydown", function (event) {
      var index = tabs.indexOf(tab);
      var next = null;
      if (event.key === "ArrowRight") next = tabs[(index + 1) % tabs.length];
      else if (event.key === "ArrowLeft") next = tabs[(index - 1 + tabs.length) % tabs.length];
      else if (event.key === "Home") next = tabs[0];
      else if (event.key === "End") next = tabs[tabs.length - 1];
      if (next) {
        event.preventDefault();
        select(next, true);
      }
    });
  });

  // ---- map circle -------------------------------------------------------
  var control = root.querySelector("[data-ring-control]");
  var checkbox = root.querySelector("#nb-ring");
  var note = root.querySelector("[data-ring-note]");
  var EARTH_RADIUS_M = 6371008.8;
  var SOURCE_ID = "nearby-distance";
  var shown = false;

  function circleRing(lng, lat, radiusM) {
    var rad = function (d) { return (d * Math.PI) / 180; };
    var deg = function (r) { return (r * 180) / Math.PI; };
    var lat1 = rad(lat);
    var lng1 = rad(lng);
    var delta = radiusM / EARTH_RADIUS_M;
    var ring = [];
    for (var i = 0; i < 64; i += 1) {
      var bearing = (2 * Math.PI * i) / 64;
      var sinLat2 = Math.sin(lat1) * Math.cos(delta) + Math.cos(lat1) * Math.sin(delta) * Math.cos(bearing);
      var lat2 = Math.asin(Math.max(-1, Math.min(1, sinLat2)));
      var lng2 = lng1 + Math.atan2(
        Math.sin(bearing) * Math.sin(delta) * Math.cos(lat1),
        Math.cos(delta) - Math.sin(lat1) * Math.sin(lat2)
      );
      ring.push([deg(lng2), Math.max(-85, Math.min(85, deg(lat2)))]);
    }
    ring.push(ring[0]);
    return ring;
  }

  function clearRing(map) {
    try {
      if (map.getLayer(SOURCE_ID)) map.removeLayer(SOURCE_ID);
      if (map.getSource(SOURCE_ID)) map.removeSource(SOURCE_ID);
    } catch (err) {
      console.error("Distance circle cleanup failed:", err);
    }
  }

  function updateRing() {
    var detail = window.dimoraDetailMap;
    if (!detail || !detail.map || !checkbox) return;
    var map = detail.map;
    clearRing(map);
    shown = false;
    if (!checkbox.checked || !current || !rings[current]) {
      if (note) note.textContent = "";
      return;
    }
    var ring = rings[current];
    try {
      var coordinates = circleRing(detail.lng, detail.lat, ring.radiusM);
      map.addSource(SOURCE_ID, {
        type: "geojson",
        data: { type: "Feature", properties: {}, geometry: { type: "LineString", coordinates: coordinates } },
      });
      map.addLayer({
        id: SOURCE_ID,
        type: "line",
        source: SOURCE_ID,
        paint: { "line-color": "#7c2d12", "line-width": 2, "line-dasharray": [2, 2] },
      });
      var minLng = Infinity, minLat = Infinity, maxLng = -Infinity, maxLat = -Infinity;
      coordinates.forEach(function (p) {
        minLng = Math.min(minLng, p[0]); maxLng = Math.max(maxLng, p[0]);
        minLat = Math.min(minLat, p[1]); maxLat = Math.max(maxLat, p[1]);
      });
      map.fitBounds([[minLng, minLat], [maxLng, maxLat]], { padding: 24, maxZoom: 15 });
      shown = true;
      if (note) {
        note.textContent =
          "Dashed circle: the nearest " + ring.label.toLowerCase() +
          " is about " + ring.radiusM + " m from the approximate centre.";
      }
    } catch (err) {
      console.error("Distance circle failed:", err);
      checkbox.checked = false;
      if (note) note.textContent = "The circle could not be drawn.";
    }
  }

  function offerRing() {
    if (!control || !checkbox || !window.dimoraDetailMap) return;
    control.hidden = false;
    checkbox.addEventListener("change", updateRing);
  }

  if (window.dimoraDetailMap) offerRing();
  else window.addEventListener("dimora:map-loaded", offerRing, { once: true });

  select(tabs[0], false);
})();

// Search map and list/map toggle on /listings (P06-T04).
//
// Progressive enhancement: the page works as a list without this script. The
// "Show map" button stays hidden unless Mapbox GL and a public token are there.
//
// Data comes from GET /api/search/map (GeoJSON of the stays' APPROXIMATE points,
// at most 200). The URL filters are passed on through data-query; the box of the
// map is added as bbox=west,south,east,north. Everything that comes from the
// server (titles, prices, links) is only ever inserted as text or as a checked
// same-site link, never as HTML.
(function () {
  const el = document.getElementById("search-map");
  const toggle = document.getElementById("map-toggle");
  const panel = document.getElementById("search-map-panel");
  const split = document.getElementById("search-split");
  const results = document.getElementById("results");
  if (!el || !toggle || !panel || !split) return;
  if (typeof mapboxgl === "undefined" || !el.dataset.token) return; // list only

  const statusEl = document.getElementById("map-status");
  const follow = document.getElementById("map-follow");
  const searchArea = document.getElementById("map-search-area");

  const SOURCE = "stays";
  const DEFAULT_CENTER = [78.9629, 20.5937]; // India (ADR-008), until the results say otherwise
  const DEFAULT_ZOOM = 3.5;
  const SINGLE_STAY_ZOOM = 13;
  const MOVE_DEBOUNCE_MS = 400;
  const LOAD_TIMEOUT_MS = 10000;
  const FONT = ["DIN Pro Medium", "Arial Unicode MS Bold"];

  let map = null;
  let loaded = false;
  let failed = false;
  let programmatic = false; // true while the script itself moves the map
  let request = null;
  let timer = null;
  let popup = null;

  // "Reduce motion" is honoured here too: Mapbox animates by itself (its default
  // for easeTo is 500 ms), so every move it makes states its duration (P18-T04).
  const reducedMotion =
    typeof matchMedia === "function" &&
    matchMedia("(prefers-reduced-motion: reduce)").matches;
  const MOVE_MS = reducedMotion ? 0 : 250; // essential feedback never takes longer than 300 ms

  function say(message) {
    if (statusEl) statusEl.textContent = message;
  }

  // Colours come from the CSS tokens, so the map follows the site's palette.
  function token(name, fallback) {
    try {
      const value = getComputedStyle(document.documentElement).getPropertyValue(name);
      return value && value.trim() ? value.trim() : fallback;
    } catch (err) {
      return fallback;
    }
  }

  function bboxOfMap() {
    const bounds = map.getBounds();
    return [bounds.getWest(), bounds.getSouth(), bounds.getEast(), bounds.getNorth()];
  }

  function fail(message) {
    if (failed) return;
    failed = true;
    el.classList.remove("is-loading");
    say(message);
    el.classList.add("map-unavailable");
  }

  function highlight(id) {
    if (!loaded || failed) return;
    map.setFilter("stay-highlight", [
      "all",
      ["!", ["has", "point_count"]],
      ["==", ["get", "id"], id || ""],
    ]);
  }

  function cardFor(id) {
    return results ? results.querySelector('[data-listing-id="' + id + '"]') : null;
  }

  function fitTo(features) {
    if (!features.length) return;
    programmatic = true;
    if (features.length === 1) {
      map.easeTo({ center: features[0].geometry.coordinates, zoom: SINGLE_STAY_ZOOM, duration: 0 });
      return;
    }
    let minLng = Infinity;
    let minLat = Infinity;
    let maxLng = -Infinity;
    let maxLat = -Infinity;
    features.forEach(function (feature) {
      const c = feature.geometry.coordinates;
      minLng = Math.min(minLng, c[0]);
      maxLng = Math.max(maxLng, c[0]);
      minLat = Math.min(minLat, c[1]);
      maxLat = Math.max(maxLat, c[1]);
    });
    map.fitBounds(
      [
        [minLng, minLat],
        [maxLng, maxLat],
      ],
      { padding: 48, maxZoom: 14, duration: 0 },
    );
  }

  // Loads the stays (for `bbox`, or everywhere when null) into the map.
  function load(bbox, options) {
    const fit = Boolean(options && options.fit);
    if (request && typeof request.abort === "function") request.abort();
    const controller = typeof AbortController === "function" ? new AbortController() : null;
    request = controller;

    const params = new URLSearchParams(el.dataset.query || "");
    if (bbox) params.set("bbox", bbox.join(","));
    say("Loading stays on the map\u2026");
    el.classList.add("is-loading");

    return fetch((el.dataset.endpoint || "/api/search/map") + "?" + params.toString(), {
      headers: { Accept: "application/json" },
      credentials: "same-origin",
      signal: controller ? controller.signal : undefined,
    })
      .then(function (response) {
        if (!response.ok) throw new Error("HTTP " + response.status);
        return response.json();
      })
      .then(function (data) {
        el.classList.remove("is-loading");
        map.getSource(SOURCE).setData(data);
        const meta = data.meta || {};
        say(meta.message || String(meta.returned || 0) + (meta.returned === 1 ? " stay" : " stays") + " on the map.");
        if (fit) fitTo(data.features || []);
        return data;
      })
      .catch(function (err) {
        if (err && err.name === "AbortError") return null;
        el.classList.remove("is-loading");
        console.error("Map results failed to load:", err);
        say("The stays could not be loaded for the map.");
        return null;
      });
  }

  function showPopup(feature) {
    const p = feature.properties || {};
    const node = document.createElement("div");
    const heading = document.createElement("h3");
    heading.className = "search-map-popup-title";
    heading.textContent = p.title || "Stay";
    node.append(heading);
    if (p.priceLabel) {
      const price = document.createElement("p");
      price.textContent = p.priceLabel + " / night";
      node.append(price);
    }
    if (typeof p.url === "string" && p.url.indexOf("/listings/") === 0) {
      const link = document.createElement("a");
      link.href = p.url;
      link.textContent = "View stay";
      node.append(link);
    }
    if (popup && typeof popup.remove === "function") popup.remove();
    popup = new mapboxgl.Popup({ offset: 14 })
      .setLngLat(feature.geometry.coordinates.slice())
      .setDOMContent(node)
      .addTo(map);
  }

  function addLayers() {
    const primary = token("--color-primary", "#0f766e");
    const text = token("--color-text", "#1f2933");
    const surface = token("--color-surface-raised", "#ffffff");

    map.addSource(SOURCE, {
      type: "geojson",
      data: { type: "FeatureCollection", features: [] },
      cluster: true,
      clusterRadius: 50,
      clusterMaxZoom: 13,
    });
    map.addLayer({
      id: "stay-clusters",
      type: "circle",
      source: SOURCE,
      filter: ["has", "point_count"],
      paint: {
        "circle-color": primary,
        "circle-radius": ["step", ["get", "point_count"], 16, 10, 20, 50, 26],
        "circle-stroke-width": 2,
        "circle-stroke-color": surface,
      },
    });
    map.addLayer({
      id: "stay-cluster-count",
      type: "symbol",
      source: SOURCE,
      filter: ["has", "point_count"],
      layout: { "text-field": ["get", "point_count_abbreviated"], "text-font": FONT, "text-size": 13 },
      paint: { "text-color": surface },
    });
    map.addLayer({
      id: "stay-highlight",
      type: "circle",
      source: SOURCE,
      filter: ["all", ["!", ["has", "point_count"]], ["==", ["get", "id"], ""]],
      paint: { "circle-color": primary, "circle-opacity": 0.25, "circle-radius": 24 },
    });
    map.addLayer({
      id: "stay-label",
      type: "symbol",
      source: SOURCE,
      filter: ["!", ["has", "point_count"]],
      layout: {
        "text-field": ["case", ["==", ["get", "priceLabel"], ""], "Stay", ["get", "priceLabel"]],
        "text-font": FONT,
        "text-size": 13,
        "text-allow-overlap": true,
      },
      paint: { "text-color": text, "text-halo-color": surface, "text-halo-width": 3 },
    });

    map.on("click", "stay-clusters", function (event) {
      const feature = event.features && event.features[0];
      if (!feature) return;
      const source = map.getSource(SOURCE);
      source.getClusterExpansionZoom(feature.properties.cluster_id, function (err, zoom) {
        if (err) return;
        map.easeTo({ center: feature.geometry.coordinates, zoom: zoom, duration: MOVE_MS });
      });
    });
    map.on("click", "stay-label", function (event) {
      if (event.features && event.features[0]) showPopup(event.features[0]);
    });

    map.on("mouseenter", "stay-label", function (event) {
      map.getCanvas().style.cursor = "pointer";
      const feature = event.features && event.features[0];
      const card = feature && cardFor(feature.properties.id);
      if (card) card.classList.add("is-highlighted");
    });
    map.on("mouseleave", "stay-label", function () {
      map.getCanvas().style.cursor = "";
      if (!results) return;
      results.querySelectorAll(".is-highlighted").forEach(function (card) {
        card.classList.remove("is-highlighted");
      });
    });
    map.on("mouseenter", "stay-clusters", function () {
      map.getCanvas().style.cursor = "pointer";
    });
    map.on("mouseleave", "stay-clusters", function () {
      map.getCanvas().style.cursor = "";
    });
  }

  function onMoved() {
    if (programmatic) {
      programmatic = false;
      return;
    }
    if (follow && follow.checked) {
      clearTimeout(timer);
      timer = setTimeout(function () {
        load(bboxOfMap());
      }, MOVE_DEBOUNCE_MS);
    } else if (searchArea) {
      searchArea.hidden = false;
    }
  }

  function start() {
    if (map || failed) return;
    try {
      map = new mapboxgl.Map({
        accessToken: el.dataset.token,
        container: el,
        style: "mapbox://styles/mapbox/streets-v12",
        center: DEFAULT_CENTER,
        zoom: DEFAULT_ZOOM,
      });
      if (typeof map.addControl === "function" && typeof mapboxgl.NavigationControl === "function") {
        map.addControl(new mapboxgl.NavigationControl({ showCompass: false }), "top-right");
      }
      map.on("load", function () {
        loaded = true;
        addLayers();
        load(null, { fit: true });
      });
      map.on("moveend", onMoved);
      map.on("error", function (event) {
        if (loaded) return;
        console.error("Search map failed to load:", event && event.error);
        fail("The map could not be loaded. The list shows the same stays.");
      });
      setTimeout(function () {
        if (!loaded) fail("The map could not be loaded. The list shows the same stays.");
      }, LOAD_TIMEOUT_MS);
    } catch (err) {
      console.error("Search map failed to load:", err);
      fail("The map could not be loaded. The list shows the same stays.");
    }
  }

  function setView(view) {
    const showMap = view === "map";
    split.dataset.view = showMap ? "map" : "list";
    panel.hidden = !showMap;
    toggle.textContent = showMap ? "Hide map" : "Show map";
    toggle.setAttribute("aria-pressed", showMap ? "true" : "false");
    if (showMap) {
      start();
      if (map && loaded && typeof map.resize === "function") map.resize();
    }
  }

  toggle.hidden = false;
  toggle.addEventListener("click", function () {
    setView(split.dataset.view === "map" ? "list" : "map");
  });

  if (searchArea) {
    searchArea.addEventListener("click", function () {
      searchArea.hidden = true;
      if (loaded) load(bboxOfMap());
    });
  }
  if (follow) {
    follow.addEventListener("change", function () {
      if (!follow.checked) return;
      if (searchArea) searchArea.hidden = true;
      if (loaded) load(bboxOfMap());
    });
  }

  // A card and its price label on the map light up together.
  if (results) {
    results.addEventListener("mouseover", function (event) {
      const card = event.target && event.target.closest ? event.target.closest("[data-listing-id]") : null;
      if (card) highlight(card.dataset.listingId);
    });
    results.addEventListener("mouseout", function () {
      highlight("");
    });
    results.addEventListener("focusin", function (event) {
      const card = event.target && event.target.closest ? event.target.closest("[data-listing-id]") : null;
      if (card) highlight(card.dataset.listingId);
    });
    results.addEventListener("focusout", function () {
      highlight("");
    });
  }
})();

const { neighborhoodFor } = require("../services/neighborhood");
const Listing = require("../models/listing.js");
const User = require("../models/user");
const Reservation = require("../models/reservation");
const { loadTrust } = require("../services/trust");
const ListingStat = require("../models/listingStat");
const { VARIANTS, recordClick } = require("../services/rankingStats");
const reviewService = require("../services/reviews");
const { summarizeRatings } = require("../utils/ratings");
const { can } = require("../policies");
const { searchPage } = require("../services/search");
const { isAdmin } = require("../policies/shared");
const { getGeocodingClient } = require("../services/geocoding");
const { deleteImage } = require("../config/cloudinary");
const { galleryOf, replaceCover } = require("../services/images");
const { imageUrl } = require("../utils/imageUrl");
const { publicPointOf } = require("../utils/geo");
const { accessibilityLabels } = require("../utils/accessibility");
const { ACCESSIBILITY_NOTICE } = require("../config/constants");
const { isPublic } = require("../utils/visibility");
const { softDeleteListing } = require("../services/lifecycle");
const { stayRulesFor } = require("../services/bookingRules");
const { todayIn, tryParseDateOnly, formatDateOnly } = require("../utils/dates");
const { evaluateReadiness } = require("../services/readiness");
const { NotFoundError, ConflictError } = require("../utils/errors");
const {
  rupeesToMinor,
  addressFromLegacy,
  imagesFromCover,
} = require("../utils/listingFields");

// The sort choices offered on the listings page, in the order shown.
const SORT_OPTIONS = [
  { value: "relevance", label: "Best match" },
  { value: "price_asc", label: "Price: low to high" },
  { value: "price_desc", label: "Price: high to low" },
  { value: "rating", label: "Top rated" },
  { value: "newest", label: "Newest" },
];

// server.js calls this at startup so a malformed MAPBOX_SERVER_TOKEN still
// stops the server at boot (the client is otherwise built on first use).
module.exports.initGeocoding = getGeocodingClient;

module.exports.index = async (req, res) => {
  // Only published listings are public (the search filter says so); results are
  // sorted and 12 to a page. The URL names and filter forms are P05-T02/T04.
  const results = await searchPage(Listing, req.query);
  res.render("listings/index.ejs", {
    allListings: results.listings,
    results,
    sortOptions: SORT_OPTIONS,
    pageTitle:
      results.page > 1 && !results.outOfRange
        ? `Explore stays (page ${results.page})`
        : "Explore stays",
    pageDescription: "Browse places to stay on Dimora.",
  });
};

module.exports.renderNewForm = (req, res) => {
  res.render("listings/new.ejs", {
    pageTitle: "List your place",
    pageDescription: "Add your home to Dimora and welcome guests.",
  });
};

// What the date picker on the detail page needs. The dates in `?in=&out=` (from
// a search) pre-fill it, but only real YYYY-MM-DD strings are used; the script
// re-checks them against the availability data.
function datePickerFor(listing, query) {
  const rules = stayRulesFor(listing, { today: todayIn() });
  const read = (value) => {
    const date = typeof value === "string" ? tryParseDateOnly(value) : null;
    return date ? formatDateOnly(date) : "";
  };
  // The booking panel (P08-T02): how many guests the select offers and which
  // one starts selected (`?guests=`, kept inside 1..capacity).
  const capacity =
    Number.isInteger(rules.capacity) && rules.capacity >= 1
      ? rules.capacity
      : 1;
  const wanted =
    typeof query.guests === "string" && /^\d{1,3}$/.test(query.guests)
      ? Number(query.guests)
      : 2;
  return {
    url: `/api/listings/${listing._id}/availability`,
    rules,
    initialIn: read(query.in),
    initialOut: read(query.out),
    quote: {
      url: `/api/listings/${listing._id}/quote`,
      checkoutUrl: `/listings/${listing._id}/checkout`,
      capacity,
      guests: Math.min(Math.max(wanted, 1), capacity),
    },
  };
}

/** A copy of a listing's reviews, newest first. */
function newestFirst(reviews) {
  const when = (review) => {
    if (
      review &&
      review.createdAt &&
      typeof review.createdAt.getTime === "function"
    ) {
      const t = review.createdAt.getTime();
      if (!Number.isNaN(t)) return t;
    }
    const id =
      review && review._id && typeof review._id.getTimestamp === "function"
        ? review._id.getTimestamp()
        : null;
    return id ? id.getTime() : 0;
  };
  return (Array.isArray(reviews) ? [...reviews] : []).sort(
    (a, b) => when(b) - when(a),
  );
}

module.exports.showListings = async (req, res) => {
  const { id } = req.params;

  const listing = await Listing.findById(id)
    .populate({
      path: "reviews",
      populate: {
        path: "author",
      },
    })
    .populate("owner");
  // ?preview=1 is the host's "see it as a guest" view: only the host, and a
  // plain 404 for everybody else (it never reveals that the listing exists).
  const preview = req.query.preview === "1";
  if (
    preview &&
    (!listing || listing.deletedAt || !can("listing:edit", req.user, listing))
  ) {
    throw new NotFoundError("That listing does not exist.");
  }

  // A deleted listing is gone for everyone. A draft or unpublished one is
  // visible to its host and to admins only; to everyone else it looks exactly
  // like a listing that does not exist.
  const visible =
    listing &&
    !listing.deletedAt &&
    (isPublic(listing) ||
      can("listing:edit", req.user, listing) ||
      isAdmin(req.user));
  if (!visible) {
    req.flash("error", "Listing you requested for does not exist");
    return res.redirect("/listings");
  }

  // Only the validated coordinates reach the page (as data- attributes); the
  // whole listing document is never serialised into a script.
  // Offer the review form only to a guest with a completed, unreviewed stay
  // inside the review window (P12-T01). `submit` decides again on the POST.
  const reviewable =
    req.user && !preview
      ? await reviewService.findReviewable({
          user: req.user,
          listingId: listing._id,
          windowDays: req.app.locals.reviewWindowDays,
        })
      : null;

  // Reviews newest first; a review without a date (written before timestamps)
  // is dated by its id. The summary is the stored totals (one atomic update per
  // review, services/ratings.js); a listing that has none yet is counted from
  // the reviews it holds.
  const reviewList = newestFirst(listing.reviews);
  const ratingSummary =
    listing.ratingCount > 0
      ? {
          average:
            Math.round((listing.ratingSum / listing.ratingCount) * 10) / 10,
          count: listing.ratingCount,
        }
      : summarizeRatings(reviewList);

  // Opened from a Best-match results page (?from=default|work|family|weekend):
  // count it once per listing per session, for the ranking comparison (P15-T06).
  // A counter only; a wrong value is ignored; a failure never shows.
  const from = typeof req.query.from === "string" ? req.query.from : "";
  if (VARIANTS.includes(from) && req.session && isPublic(listing)) {
    const seen = Array.isArray(req.session.rankClicks) ? req.session.rankClicks : [];
    if (!seen.includes(String(listing._id))) {
      req.session.rankClicks = [...seen, String(listing._id)].slice(-50);
      recordClick({ ListingStat, listingId: listing._id, variant: from }).catch(() => {});
    }
  }

  // The host's confirmed facts (P12-T05). A failure here must not take the page down.
  let hostTrust = null;
  try {
    hostTrust = listing.owner
      ? await loadTrust({ User, Reservation }, listing.owner)
      : null;
  } catch {
    hostTrust = null;
  }

  res.render("listings/show.ejs", {
    listing,
    hostTrust,
    reviewable,
    reviewList,
    ratingSummary,
    gallery,
    // The first photo, large, for the Open Graph tags (P18-T05); only an https
    // address is used (the layout checks again).
    pageImage: gallery[0] ? imageUrl(gallery[0].url, "full") : "",
    // Host-declared, not verified (P15-T05).
    accessibility: {
      labels: accessibilityLabels(listing.accessibility),
      notice: ACCESSIBILITY_NOTICE,
    },
    // The public (approximate) point only: the precise one never reaches a page.
    mapPoint: publicPointOf(listing),
    // Stored places around the stay (P15-T02): read from the listing, no network.
    neighborhood: neighborhoodFor(listing),
    guestView: preview,
    datePicker: datePickerFor(listing, req.query),
    readiness:
      !isPublic(listing) && can("listing:edit", req.user, listing)
        ? evaluateReadiness(listing)
        : null,
    pageTitle: listing.title,
    pageDescription: listing.description,
  });
};
// Runs after validateListing, requireImage, geocodeListing and uploadToCloudinary
// (see routes/listing.js): req.body.listing is clean, req.geometry is set and
// req.file.path / req.file.filename point at the uploaded image.
module.exports.createListing = async (req, res) => {
  const { title, description, location, country, price } = req.body.listing;
  const cover = { url: req.file.path, filename: req.file.filename };

  const newListing = new Listing({
    title,
    description,
    location,
    country,
    // The old form has no draft step, so a listing is public as soon as it is
    // saved. The wizard (P04-T02) creates drafts and P04-T05 publishes them.
    status: "published",
    pricing: { nightlyMinor: rupeesToMinor(price), currency: "INR" },
    // The form asks for free text; the structured address is a guess the host
    // confirms later (P04-T04).
    address: addressFromLegacy(location, country),
    needsReview: true,
    owner: req.user._id,
    geometry: req.geometry,
    image: cover,
    images: imagesFromCover(cover),
  });

  try {
    await newListing.save();
  } catch (err) {
    await deleteImage(req.file.filename, req.log); // do not orphan the upload
    throw err;
  }

  req.flash("success", "New Listing Created");
  res.redirect("/listings");
};
// The image is optional on edit: without a new file the stored image stays.
// With one, the old image is deleted from Cloudinary after the save succeeds.
module.exports.updateListing = async (req, res) => {
  const { id } = req.params;
  const listing = req.listing; // loaded by authorize("listing:edit")
  const { title, description, location, country, price } = req.body.listing;

  let previousFilename;

  listing.set({ title, description, location, country });
  listing.set("pricing.nightlyMinor", rupeesToMinor(price));
  // While the address is still the guess made from the old text fields, keep it
  // in step with them; a confirmed address (needsReview false) is left alone.
  if (listing.needsReview)
    listing.address = addressFromLegacy(location, country);
  if (req.geometry) listing.geometry = req.geometry;
  if (req.file) {
    // The single-photo field replaces the cover; the rest of the gallery stays.
    previousFilename = replaceCover(listing, {
      url: req.file.path,
      publicId: req.file.filename,
    });
  }

  try {
    await listing.save();
  } catch (err) {
    if (req.file) await deleteImage(req.file.filename, req.log);
    throw err;
  }

  if (req.file && previousFilename) {
    await deleteImage(previousFilename, req.log);
  }

  req.flash("success", "Listing Updated");
  res.redirect(`/listings/${id}`);
};

module.exports.destroyListing = async (req, res) => {
  const { id } = req.params;

  // Soft delete (P04-T05): hidden for good, but the row stays so reviews and
  // reservations remain readable. Refused while a reservation is upcoming.
  try {
    await softDeleteListing(req.listing || (await Listing.findById(id)));
  } catch (err) {
    if (err instanceof ConflictError) {
      req.flash("error", err.message);
      return res.redirect(`/host/listings/${id}/status`);
    }
    throw err;
  }
  req.flash("success", "Listing Deleted");

  res.redirect(`/listings`);
};

// Audit service (P14-T01). Every administrative action writes exactly one row
// through record(), in the same request as the action (see
// src/middleware/admin.js `auditedMutation`, which enforces that). The viewer
// reads through listAudit(); nothing here updates or deletes a row.
const AuditLog = require("../models/auditLog");
const User = require("../models/user");
const { tryParseDateOnly, formatDateOnly, addDays } = require("../utils/dates");

const { TARGET_TYPES } = AuditLog;

const PAGE_SIZE = 25;

// Details are small facts about a change (old/new status...). Anything that
// looks like a credential is refused so a careless caller cannot leak one into
// a log that admins read.
const SECRET_KEY = /pass(word)?|token|secret|hash|salt|cookie|authorization/i;

function assertSafeDetails(details, path = "details") {
  if (details === undefined || details === null) return;
  if (Array.isArray(details)) {
    details.forEach((item, i) => assertSafeDetails(item, `${path}[${i}]`));
    return;
  }
  if (typeof details === "object") {
    for (const [key, value] of Object.entries(details)) {
      if (SECRET_KEY.test(key)) {
        throw new Error(`audit.record: ${path}.${key} must not be logged`);
      }
      assertSafeDetails(value, `${path}.${key}`);
    }
  }
}

/**
 * Writes one audit row and counts it on the request (`req.auditRecorded`), so
 * the auditedMutation wrapper can check it.
 *
 * @param {object} entry
 * @param {object} [entry.actor] the admin user (default: req.user)
 * @param {string} [entry.actorLabel] who acted when there is no logged-in admin
 * @param {string} entry.action e.g. "user.suspend" (lower-case, dot separated)
 * @param {string} entry.targetType user | listing | review | report | reservation | system
 * @param {*} [entry.targetId]
 * @param {string} [entry.reason]
 * @param {object} [entry.details]
 * @param {object} [entry.req] the Express request (request id, default actor)
 * @param {object} [options] { session } for a MongoDB transaction
 */
async function record(entry, options = {}) {
  const { req, reason, details } = entry;
  const actor = entry.actor || (req && req.user) || null;
  const actorLabel = entry.actorLabel;
  if (!actor && !actorLabel) {
    throw new Error("audit.record: an actor or an actorLabel is required");
  }
  assertSafeDetails(details);

  const doc = {
    actor: actor ? actor._id || actor : null,
    actorLabel: actorLabel || undefined,
    action: entry.action,
    targetType: entry.targetType,
    targetId: entry.targetId ?? null,
    reason: typeof reason === "string" && reason.trim() ? reason : undefined,
    details: details ?? undefined,
    requestId: req && req.id ? String(req.id) : undefined,
  };

  const [row] = await AuditLog.create([doc], options.session ? { session: options.session } : {});
  if (req) req.auditRecorded = (req.auditRecorded || 0) + 1;
  return row;
}

/** A positive whole page number, else 1 (never throws, never reaches the query). */
function toPageNumber(value) {
  if (typeof value !== "string" || !/^[0-9]{1,6}$/.test(value)) return 1;
  const n = Number(value);
  return n >= 1 ? n : 1;
}

const FILTER_MAX = 80;
const ACTION_PREFIX = /^[a-z][a-z0-9_.]*$/;
const escapeRegex = (text) => text.replace(/[.*+?^${}()|[\]\\]/g, "\\$&");

/**
 * The log's filters, cleaned. Text is matched as plain text; a date that is not
 * a real YYYY-MM-DD is ignored. `to` is inclusive (the whole day, UTC).
 */
function cleanFilters({ action, actor, targetType, from, to } = {}) {
  const str = (v) => (typeof v === "string" ? v.trim().slice(0, FILTER_MAX) : "");
  const fromDate = tryParseDateOnly(str(from));
  const toDate = tryParseDateOnly(str(to));
  const act = str(action).toLowerCase();
  return {
    action: ACTION_PREFIX.test(act) ? act : "",
    actor: str(actor),
    targetType: TARGET_TYPES.includes(str(targetType)) ? str(targetType) : "",
    from: fromDate ? formatDateOnly(fromDate) : "",
    to: toDate ? formatDateOnly(toDate) : "",
    fromDate,
    toDate,
  };
}

/**
 * One page of the log, newest first, for the read-only viewer, optionally
 * filtered by action (exact name or a prefix such as "user."), actor username,
 * target type and a UTC date range.
 * @returns {{rows: object[], page: number, totalPages: number, total: number, pageSize: number, filters: object}}
 */
async function listAudit({ page, ...rawFilters } = {}) {
  const f = cleanFilters(rawFilters);
  const filter = {};
  if (f.action) filter.action = new RegExp(`^${escapeRegex(f.action)}`);
  if (f.targetType) filter.targetType = f.targetType;
  if (f.actor) {
    const rx = new RegExp(`^${escapeRegex(f.actor)}$`, "i");
    const users = await User.find({ username: rx }).select("_id").limit(5).lean();
    // Rows written outside a login are labelled instead (see audit.record).
    filter.$or = [{ actor: { $in: users.map((u) => u._id) } }, { actorLabel: rx }];
  }
  if (f.fromDate || f.toDate) {
    filter.createdAt = {};
    if (f.fromDate) filter.createdAt.$gte = f.fromDate;
    if (f.toDate) filter.createdAt.$lt = addDays(f.toDate, 1);
  }

  const total = await AuditLog.countDocuments(filter);
  const totalPages = Math.max(1, Math.ceil(total / PAGE_SIZE));
  const current = Math.min(toPageNumber(page), totalPages);
  const rows = await AuditLog.find(filter)
    .sort({ createdAt: -1, _id: -1 })
    .skip((current - 1) * PAGE_SIZE)
    .limit(PAGE_SIZE)
    .populate("actor", "username displayName")
    .lean();
  const { fromDate, toDate, ...shown } = f;
  return { rows, page: current, totalPages, total, pageSize: PAGE_SIZE, filters: shown };
}

module.exports = { record, listAudit, cleanFilters, toPageNumber, PAGE_SIZE };

// Host listing statistics (P13-T03). APPROXIMATE by design, and labelled so.
//
// Counting rules
//  - A view counts once per browser session per listing per day. The "seen"
//    marks live in the session (at most MAX_SEEN of them, old days dropped).
//  - Not counted: requests with no or a bot-like User-Agent (a heuristic, so
//    some bots get through and a few odd browsers do not), the listing's own
//    host, the host's "see it as a guest" preview, and listings that are not
//    public.
//  - Counting never breaks a page: every failure is caught and logged.
//  - Counters only go up with $inc (views, checkout starts, daily saves). The
//    lifetime ListingStat.saves can be driven down by un-saves, and is clamped
//    at 0 so it is never negative.
const { todayIn, addDays, formatDateOnly, DEFAULT_TIMEZONE } = require("../utils/dates");

const WINDOW_DAYS = 30;
const MIN_VIEWS_FOR_CONVERSION = 30;
const MAX_SEEN = 100;

// Words that show up in the User-Agent of crawlers, link previewers, monitors
// and scripts. A heuristic, not a guarantee.
const BOT_UA =
  /bot|crawl|spider|slurp|preview|facebookexternalhit|embedly|monitor|uptime|pingdom|lighthouse|headless|phantomjs|puppeteer|playwright|curl|wget|httpclient|python|java\/|go-http|scrapy|axios|node-fetch|okhttp/i;

/** True for a missing, very short, or bot-like User-Agent. */
function isBot(userAgent) {
  if (typeof userAgent !== "string") return true;
  const ua = userAgent.trim();
  return ua.length < 10 || BOT_UA.test(ua);
}

const models = (deps = {}) => ({
  DayStat: deps.DayStat || require("../models/listingDayStat"),
  ListingStat: deps.ListingStat || require("../models/listingStat"),
  Reservation: deps.Reservation || require("../models/reservation"),
});

const dayOf = (now) => todayIn(DEFAULT_TIMEZONE, now);

/** $inc one counter of today's row, creating it. One retry when two requests create it at once. */
async function bump(listingId, field, { now = new Date(), deps } = {}) {
  const { DayStat } = models(deps);
  const filter = { listing: listingId, day: dayOf(now) };
  const update = { $inc: { [field]: 1 } };
  try {
    await DayStat.updateOne(filter, update, { upsert: true });
  } catch (err) {
    if (err && err.code === 11000) {
      await DayStat.updateOne(filter, update, { upsert: true });
      return;
    }
    throw err;
  }
}

/** True the first time this session sees `key` today; remembers it. */
function firstTimeToday(session, key, now) {
  if (!session || typeof session !== "object") return false;
  const today = formatDateOnly(dayOf(now));
  const seen = session.statSeen && typeof session.statSeen === "object" ? session.statSeen : {};
  const kept = {};
  for (const [k, day] of Object.entries(seen)) if (day === today) kept[k] = day;
  if (kept[key]) {
    session.statSeen = kept;
    return false;
  }
  const keys = Object.keys(kept);
  if (keys.length >= MAX_SEEN) delete kept[keys[0]];
  kept[key] = today;
  session.statSeen = kept;
  return true;
}

function shouldCount(req, listing, { preview = false } = {}) {
  if (!req || !listing || preview) return false;
  if (isBot(req.get && req.get("user-agent"))) return false;
  const owner = listing.owner && (listing.owner._id || listing.owner);
  if (req.user && owner && String(req.user._id) === String(owner)) return false;
  return true;
}

async function count(kind, req, listing, options = {}) {
  try {
    if (!shouldCount(req, listing, options)) return false;
    const now = options.now || new Date();
    const key = `${kind}:${listing._id}`;
    if (!firstTimeToday(req.session, key, now)) return false;
    await bump(listing._id, kind === "v" ? "views" : "checkoutStarts", { now, deps: options.deps });
    return true;
  } catch (err) {
    if (req && req.log) req.log.warn({ err }, "listing stat not counted");
    return false;
  }
}

/** A page view of a public listing. Never throws. */
const recordView = (req, listing, options) => count("v", req, listing, options);

/** A checkout page opened for a listing. Never throws. */
const recordCheckoutStart = (req, listing, options) => count("c", req, listing, options);

/** A stay was saved (a row was really created). Never throws. */
async function recordSave(listingId, { now, deps } = {}) {
  try {
    await bump(listingId, "saves", { now, deps });
  } catch (err) {
    // statistics must never break saving
  }
}

/** After an un-save: the lifetime total may not stay below zero. Never throws. */
async function clampSaves(listingId, { deps } = {}) {
  try {
    const { ListingStat } = models(deps);
    await ListingStat.updateOne({ listing: listingId, saves: { $lt: 0 } }, { $set: { saves: 0 } });
  } catch (err) {
    // see above
  }
}

/**
 * The last `days` days (today included) for one listing, oldest first, with
 * every day present (zeros where nothing was counted).
 * conversion = reservations created in the window / views in the window, only
 * when views >= 30 (below that a ratio says nothing); null otherwise.
 */
async function getStats(listingId, { now = new Date(), days = WINDOW_DAYS, deps } = {}) {
  const { DayStat, ListingStat, Reservation } = models(deps);
  const today = dayOf(now);
  const first = addDays(today, -(days - 1));
  const rows = await DayStat.find({ listing: listingId, day: { $gte: first, $lte: today } }).lean();
  const byDay = new Map(rows.map((r) => [formatDateOnly(r.day), r]));

  const series = [];
  const total = { views: 0, saves: 0, checkoutStarts: 0 };
  for (let i = 0; i < days; i += 1) {
    const day = addDays(first, i);
    const row = byDay.get(formatDateOnly(day)) || {};
    const point = {
      day: formatDateOnly(day),
      views: row.views || 0,
      saves: row.saves || 0,
      checkoutStarts: row.checkoutStarts || 0,
    };
    total.views += point.views;
    total.saves += point.saves;
    total.checkoutStarts += point.checkoutStarts;
    series.push(point);
  }

  const reservations = await Reservation.countDocuments({
    listing: listingId,
    createdAt: { $gte: first },
  });
  const lifetime = await ListingStat.findOne({ listing: listingId }).lean();
  const conversion =
    total.views >= MIN_VIEWS_FOR_CONVERSION
      ? Math.min(100, Math.round((reservations * 1000) / total.views) / 10)
      : null;

  return {
    days,
    from: formatDateOnly(first),
    to: formatDateOnly(today),
    series,
    total,
    reservations,
    conversion,
    minViewsForConversion: MIN_VIEWS_FOR_CONVERSION,
    savedNow: Math.max(0, (lifetime && lifetime.saves) || 0),
  };
}

module.exports = {
  isBot,
  recordView,
  recordCheckoutStart,
  recordSave,
  clampSaves,
  getStats,
  firstTimeToday,
  shouldCount,
  WINDOW_DAYS,
  MIN_VIEWS_FOR_CONVERSION,
  MAX_SEEN,
};

// Nearby places for a listing (P15-T01), from OpenStreetMap through the
// Overpass API. This is the ONLY code that calls Overpass, and it is reached
// only from: publishing a listing, a host's refresh button, the retry job and
// scripts/refresh-nearby.js. Guests and visitors only ever read what is stored
// in `listing.nearby` (a test checks that no public code imports this file).
//
// Privacy: the search is centred on the listing's PRECISE point, which never
// leaves the server. Every stored distance is measured from the PUBLIC
// (approximate) point instead. Exact distances to several places with known
// positions would let anyone work the home's position out again.
//
// What is stored (listing.nearby):
//   fetchedAt, source, key (hash of the precise point the data is for),
//   items [{ category, name, kind, distanceM }] (top 5 per category, nearest first),
//   attemptedAt, failures, nextRetryAt (set while a fetch keeps failing).
// A failed fetch never erases earlier data.
const crypto = require("node:crypto");
const {
  SOURCE,
  CATEGORIES,
  RULES,
  readNearbyConfig,
} = require("../config/nearby");
const { distanceMeters, publicPointOf, toMapPoint } = require("../utils/geo");

class NearbyUnavailableError extends Error {
  constructor(message, { retryable = true, retryAfterMs = 0 } = {}) {
    super(message);
    this.name = "NearbyUnavailableError";
    this.retryable = retryable;
    this.retryAfterMs = retryAfterMs;
  }
}

// ---- small helpers --------------------------------------------------------

/** `date` moved by `ms` (no Date constructor with an argument; see noUserDate). */
function shift(date, ms) {
  const moved = new Date();
  moved.setTime(date.getTime() + ms);
  return moved;
}

const sleepFor = (ms) => new Promise((resolve) => setTimeout(resolve, ms));

/** Same precise point -> same key; used to notice that the address moved. */
function keyFor(point) {
  return crypto
    .createHash("sha256")
    .update(`${point.lng.toFixed(5)},${point.lat.toFixed(5)}`)
    .digest("hex")
    .slice(0, 16);
}

// Control characters and bidi overrides can hide or reorder text.
const UNSAFE_CHARS = /[\u0000-\u001F\u007F-\u009F\u200E\u200F\u202A-\u202E\u2066-\u2069]/g;

/** Plain text, one line, at most 100 characters. HTML is NOT removed: every view escapes with <%= %>. */
function cleanName(value) {
  if (typeof value !== "string") return null;
  const text = value.replace(UNSAFE_CHARS, " ").replace(/\s+/g, " ").trim().slice(0, 100);
  return text || null;
}

function kindOf(tags) {
  const raw =
    tags.amenity || tags.shop || tags.leisure || tags.highway || tags.railway || tags.public_transport;
  return typeof raw === "string" && /^[a-z_]{1,40}$/.test(raw) ? raw : null;
}

// ---- query and parser -----------------------------------------------------

/** Overpass QL for one category around the precise point. */
function buildQuery(point, category, { maxElements = RULES.maxElements } = {}) {
  const around = `(around:${category.radiusM},${point.lat.toFixed(6)},${point.lng.toFixed(6)})`;
  const parts = category.selectors.map((selector) => `  nwr${selector}${around};`);
  return [
    "[out:json][timeout:20][maxsize:33554432];",
    "(",
    ...parts,
    ");",
    `out center tags ${maxElements};`,
  ].join("\n");
}

/**
 * Overpass elements -> the top places of one category, nearest first.
 * @param {object[]} elements Overpass `elements`
 * @param {{id: string}} category
 * @param {{lng:number, lat:number}} origin where distances are measured from (the PUBLIC point)
 */
function parseElements(elements, category, origin, { topN = RULES.topN } = {}) {
  const found = [];
  for (const element of Array.isArray(elements) ? elements : []) {
    if (!element || typeof element !== "object") continue;
    const tags = element.tags && typeof element.tags === "object" ? element.tags : {};
    const lat = element.lat ?? (element.center && element.center.lat);
    const lng = element.lon ?? (element.center && element.center.lon);
    const place = toMapPoint({ type: "Point", coordinates: [lng, lat] });
    if (!place) continue;
    const name = cleanName(tags.name) || cleanName(tags["name:en"]);
    const kind = kindOf(tags);
    found.push({
      category: category.id,
      name,
      kind,
      // Rounded to 10 m: more precision would only pretend to be accurate.
      distanceM: Math.round(distanceMeters(origin, place) / 10) * 10,
    });
  }
  found.sort((a, b) => a.distanceM - b.distanceM || String(a.name).localeCompare(String(b.name)));

  // OpenStreetMap often has two entries for one place (a node and a building)
  // and chains repeat: keep the nearest of each name (or of each unnamed kind).
  const seen = new Set();
  const items = [];
  for (const item of found) {
    const key = item.name ? item.name.toLowerCase() : `(${item.kind})`;
    if (seen.has(key)) continue;
    seen.add(key);
    items.push(item);
    if (items.length >= topN) break;
  }
  return items;
}

// ---- Overpass client (one at a time, one retry) ---------------------------

let tail = Promise.resolve();
/** Global concurrency 1: tasks run strictly one after another in this process. */
function serial(task) {
  const run = tail.then(task, task);
  tail = run.catch(() => {});
  return run;
}

async function requestOnce(query, { fetchImpl, config }) {
  let response;
  try {
    response = await fetchImpl(config.endpoint, {
      method: "POST",
      headers: {
        "User-Agent": config.userAgent,
        Accept: "application/json",
        "Content-Type": "application/x-www-form-urlencoded",
      },
      body: new URLSearchParams({ data: query }).toString(),
      signal: AbortSignal.timeout(RULES.requestTimeoutMs),
    });
  } catch (err) {
    throw new NearbyUnavailableError(`Overpass did not answer (${err && err.name ? err.name : "error"})`);
  }
  if (response.status === 429 || response.status >= 500) {
    const seconds = Number(response.headers && response.headers.get && response.headers.get("retry-after"));
    throw new NearbyUnavailableError(`Overpass is busy or down (HTTP ${response.status})`, {
      retryAfterMs: Number.isFinite(seconds) && seconds > 0 ? seconds * 1000 : 0,
    });
  }
  if (!response.ok) {
    throw new NearbyUnavailableError(`Overpass refused the query (HTTP ${response.status})`, { retryable: false });
  }
  let body;
  try {
    body = await response.json();
  } catch {
    throw new NearbyUnavailableError("Overpass sent something that is not JSON");
  }
  // A query that ran out of time or memory can still answer 200, with a remark.
  if (body && typeof body.remark === "string" && /runtime error|timed out|out of memory/i.test(body.remark)) {
    throw new NearbyUnavailableError("Overpass could not finish the query in time");
  }
  if (!body || !Array.isArray(body.elements)) {
    throw new NearbyUnavailableError("Overpass sent an unexpected answer", { retryable: false });
  }
  return body.elements;
}

/** One request, with exactly one retry after a pause (Retry-After if given, capped). */
async function overpass(query, { fetchImpl, config, sleep }) {
  try {
    return await requestOnce(query, { fetchImpl, config });
  } catch (err) {
    if (!(err instanceof NearbyUnavailableError) || !err.retryable) throw err;
    await sleep(Math.min(err.retryAfterMs || RULES.retryPauseMs, RULES.maxRetryAfterMs));
    return requestOnce(query, { fetchImpl, config });
  }
}

// ---- when may we fetch? ---------------------------------------------------

/**
 * @returns {{ ok: true } | { ok: false, reason: "fresh"|"cooldown"|"throttled", retryAt: Date|null }}
 */
function mayFetch(stored, key, { manual, now }) {
  const n = stored || {};
  const sameSpot = n.key === key;
  if (n.attemptedAt && now.getTime() - n.attemptedAt.getTime() < RULES.attemptThrottleMs) {
    return { ok: false, reason: "throttled", retryAt: shift(n.attemptedAt, RULES.attemptThrottleMs) };
  }
  if (n.fetchedAt && sameSpot) {
    const age = now.getTime() - n.fetchedAt.getTime();
    if (manual && age < RULES.manualCooldownMs) {
      return { ok: false, reason: "cooldown", retryAt: shift(n.fetchedAt, RULES.manualCooldownMs) };
    }
    if (!manual && age < RULES.freshMs) {
      return { ok: false, reason: "fresh", retryAt: shift(n.fetchedAt, RULES.freshMs) };
    }
  }
  return { ok: true };
}

/** For the host button: can this listing be refreshed now? (no network, no writes) */
function manualVerdict(listing, { now = new Date(), config = readNearbyConfig() } = {}) {
  if (!config.enabled) return { ok: false, reason: "disabled", retryAt: null };
  const precise = toMapPoint(listing && listing.geometry);
  if (!precise) return { ok: false, reason: "no_location", retryAt: null };
  return mayFetch(listing.nearby, keyFor(precise), { manual: true, now });
}

// ---- the refresh ----------------------------------------------------------

function loadListingModel(deps) {
  return deps.Listing || require("../models/listing");
}

/**
 * Fetches and stores the nearby places of one published listing.
 * Never throws for an Overpass problem: it reports `failed` and schedules a retry.
 * @returns {Promise<{status: "disabled"|"skipped"|"no_location"|"fresh"|"cooldown"|"throttled"|"updated"|"failed", ...}>}
 */
async function refreshListing(listing, { manual = false, now = new Date(), deps = {} } = {}) {
  const config = deps.config || readNearbyConfig();
  if (!config.enabled) return { status: "disabled" };
  if (!listing || listing.status !== "published" || listing.deletedAt) return { status: "skipped" };

  const precise = toMapPoint(listing.geometry);
  const origin = precise && publicPointOf(listing);
  if (!precise || !origin) return { status: "no_location" };

  const key = keyFor(precise);
  const verdict = mayFetch(listing.nearby, key, { manual, now });
  if (!verdict.ok) return { status: verdict.reason, retryAt: verdict.retryAt };

  const Listing = loadListingModel(deps);
  const fetchImpl = deps.fetch || globalThis.fetch;
  const sleep = deps.sleep || sleepFor;
  const log = deps.log || { info() {}, warn() {} };

  return serial(async () => {
    try {
      const items = [];
      for (const category of CATEGORIES) {
        const elements = await overpass(buildQuery(precise, category), { fetchImpl, config, sleep });
        items.push(...parseElements(elements, category, origin));
      }
      await Listing.updateOne(
        { _id: listing._id },
        {
          $set: {
            nearby: {
              fetchedAt: now,
              attemptedAt: now,
              source: SOURCE,
              key,
              items,
              failures: 0,
              nextRetryAt: null,
            },
          },
        },
      );
      log.info({ listingId: String(listing._id), places: items.length }, "nearby places updated");
      return { status: "updated", count: items.length };
    } catch (err) {
      if (!(err instanceof NearbyUnavailableError)) throw err;
      const failures = ((listing.nearby && listing.nearby.failures) || 0) + 1;
      const wait = RULES.retryBackoffMs[Math.min(failures - 1, RULES.retryBackoffMs.length - 1)];
      const nextRetryAt = shift(now, wait);
      // Dot paths: whatever was stored before stays.
      await Listing.updateOne(
        { _id: listing._id },
        { $set: { "nearby.attemptedAt": now, "nearby.failures": failures, "nearby.nextRetryAt": nextRetryAt } },
      );
      log.warn({ listingId: String(listing._id), failures, reason: err.message }, "nearby places not updated");
      return { status: "failed", failures, nextRetryAt, reason: err.message };
    }
  });
}

/**
 * Fire and forget: loads the listing and refreshes it in the background so a
 * slow Overpass never delays publishing. Every error is logged, none escapes.
 */
function scheduleRefresh(listingId, { manual = false, deps = {} } = {}) {
  let config;
  try {
    config = deps.config || readNearbyConfig();
  } catch (err) {
    if (deps.log) deps.log.warn({ err: err.message }, "nearby places not configured");
    return;
  }
  if (!config.enabled) return;
  const log = deps.log || { info() {}, warn() {} };
  setImmediate(async () => {
    try {
      const listing = await loadListingModel(deps).findById(listingId).lean();
      await refreshListing(listing, { manual, deps: { ...deps, config } });
    } catch (err) {
      log.warn({ listingId: String(listingId), err: err && err.message }, "nearby refresh crashed");
    }
  });
}

// ---- what the host page shows --------------------------------------------

/** Counts and names of what is stored, for the host's status page. No network. */
function summaryFor(listing, { now = new Date(), config } = {}) {
  const cfg = config || readNearbyConfig();
  const stored = (listing && listing.nearby) || {};
  const items = Array.isArray(stored.items) ? stored.items : [];
  const verdict = manualVerdict(listing, { now, config: cfg });
  return {
    enabled: cfg.enabled,
    fetchedOn: stored.fetchedAt ? stored.fetchedAt.toISOString().slice(0, 10) : null,
    source: stored.source || SOURCE,
    failing: Boolean(stored.nextRetryAt) && (stored.failures || 0) > 0,
    total: items.length,
    categories: CATEGORIES.map((c) => ({
      id: c.id,
      label: c.label,
      items: items
        .filter((i) => i.category === c.id)
        .map((i) => ({ name: i.name, kind: i.kind, distanceM: i.distanceM })),
    })),
    canRefresh: verdict.ok,
    retryOn: verdict.retryAt ? verdict.retryAt.toISOString().slice(0, 10) : null,
    refuseReason: verdict.ok ? null : verdict.reason,
  };
}

module.exports = {
  refreshListing,
  scheduleRefresh,
  manualVerdict,
  summaryFor,
  buildQuery,
  parseElements,
  cleanName,
  keyFor,
  mayFetch,
  NearbyUnavailableError,
  SOURCE,
};

